SET SERVEROUTPUT ON;
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK;
DECLARE
  v NUMBER; p NUMBER:=0; f NUMBER:=0;
  PROCEDURE ok(m VARCHAR2) IS BEGIN p:=p+1; DBMS_OUTPUT.PUT_LINE('PASS | '||m); END;
  PROCEDURE bad(m VARCHAR2) IS BEGIN f:=f+1; DBMS_OUTPUT.PUT_LINE('FAIL | '||m); END;
  FUNCTION tab(t VARCHAR2) RETURN BOOLEAN IS n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM ALL_TABLES WHERE OWNER='DPS2' AND TABLE_NAME=t; RETURN n>0; END;
  PROCEDURE chk(m VARCHAR2,b BOOLEAN) IS BEGIN IF b THEN ok(m); ELSE bad(m); END IF; END;
  PROCEDURE seq_ahead(s VARCHAR2,t VARCHAR2,pk VARCHAR2) IS mx NUMBER; nx NUMBER; BEGIN EXECUTE IMMEDIATE 'SELECT NVL(MAX('||pk||'),0) FROM DPS2.'||t INTO mx; EXECUTE IMMEDIATE 'SELECT DPS2.'||s||'.NEXTVAL FROM DUAL' INTO nx; chk(s||' ahead',nx>mx); EXCEPTION WHEN OTHERS THEN bad(s||' ahead'); END;
BEGIN
  chk('reconciliation run exists',tab('DEPOSIT_RECONCILIATION_RUN')); chk('reconciliation item exists',tab('DEPOSIT_RECONCILIATION_ITEM')); chk('discrepancy exists',tab('DEPOSIT_DISCREPANCY')); chk('suspense open item exists',tab('DEPOSIT_SUSPENSE_OPEN_ITEM'));
  chk('exception case exists',tab('DEPOSIT_EXCEPTION_CASE')); chk('exception assignment exists',tab('DEPOSIT_EXCEPTION_ASSIGNMENT')); chk('correction request exists',tab('DEPOSIT_CORRECTION_REQUEST')); chk('correction authorization exists',tab('DEPOSIT_CORRECTION_AUTHORIZATION')); chk('correction entry exists',tab('DEPOSIT_CORRECTION_ENTRY')); chk('root cause analysis exists',tab('DEPOSIT_ROOT_CAUSE_ANALYSIS'));
  chk('correspondent extension exists',tab('CORRESPONDENT_ACCOUNT_EXTENSION')); chk('correspondent profile exists',tab('CORRESPONDENT_RECONCILIATION_PROFILE'));
  chk('reward program exists',tab('DEPOSIT_REWARD_PROGRAM')); chk('reward rule exists',tab('DEPOSIT_REWARD_ELIGIBILITY_RULE')); chk('reward enrollment exists',tab('DEPOSIT_REWARD_ENROLLMENT')); chk('lottery draw exists',tab('DEPOSIT_LOTTERY_DRAW')); chk('lottery entry exists',tab('DEPOSIT_LOTTERY_ENTRY')); chk('lottery winner exists',tab('DEPOSIT_LOTTERY_WINNER'));
  seq_ahead('SEQ_DEPOSIT_RECONCILIATION_RUN','DEPOSIT_RECONCILIATION_RUN','RECONCILIATION_RUN_ID'); seq_ahead('SEQ_DEPOSIT_RECONCILIATION_ITEM','DEPOSIT_RECONCILIATION_ITEM','RECONCILIATION_ITEM_ID'); seq_ahead('SEQ_DEPOSIT_DISCREPANCY','DEPOSIT_DISCREPANCY','DISCREPANCY_ID'); seq_ahead('SEQ_DEPOSIT_SUSPENSE_OPEN_ITEM','DEPOSIT_SUSPENSE_OPEN_ITEM','SUSPENSE_OPEN_ITEM_ID');
  seq_ahead('SEQ_DEPOSIT_EXCEPTION_CASE','DEPOSIT_EXCEPTION_CASE','EXCEPTION_CASE_ID'); seq_ahead('SEQ_DEPOSIT_EXCEPTION_ASSIGNMENT','DEPOSIT_EXCEPTION_ASSIGNMENT','EXCEPTION_ASSIGNMENT_ID'); seq_ahead('SEQ_DEPOSIT_CORRECTION_REQUEST','DEPOSIT_CORRECTION_REQUEST','CORRECTION_REQUEST_ID'); seq_ahead('SEQ_DEPOSIT_CORRECTION_AUTHORIZATION','DEPOSIT_CORRECTION_AUTHORIZATION','CORRECTION_AUTHORIZATION_ID'); seq_ahead('SEQ_DEPOSIT_CORRECTION_ENTRY','DEPOSIT_CORRECTION_ENTRY','CORRECTION_ENTRY_ID'); seq_ahead('SEQ_DEPOSIT_ROOT_CAUSE_ANALYSIS','DEPOSIT_ROOT_CAUSE_ANALYSIS','ROOT_CAUSE_ANALYSIS_ID');
  seq_ahead('SEQ_CORRESPONDENT_ACCOUNT_EXTENSION','CORRESPONDENT_ACCOUNT_EXTENSION','CORRESPONDENT_ACCOUNT_EXTENSION_ID'); seq_ahead('SEQ_CORRESPONDENT_RECONCILIATION_PROFILE','CORRESPONDENT_RECONCILIATION_PROFILE','CORRESPONDENT_RECON_PROFILE_ID'); seq_ahead('SEQ_DEPOSIT_REWARD_ENROLLMENT','DEPOSIT_REWARD_ENROLLMENT','REWARD_ENROLLMENT_ID'); seq_ahead('SEQ_DEPOSIT_OPERATION_IDEMPOTENCY','DEPOSIT_OPERATION_IDEMPOTENCY','OPERATION_IDEMPOTENCY_ID');
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_RECONCILIATION_RUN R WHERE R.STATUS_CODE='COMPLETED' AND (NVL(R.TOTAL_SOURCE_AMOUNT,0)<>NVL((SELECT SUM(NVL(I.SOURCE_AMOUNT,0)) FROM DPS2.DEPOSIT_RECONCILIATION_ITEM I WHERE I.RECONCILIATION_RUN_ID=R.RECONCILIATION_RUN_ID),0) OR NVL(R.TOTAL_TARGET_AMOUNT,0)<>NVL((SELECT SUM(NVL(I.TARGET_AMOUNT,0)) FROM DPS2.DEPOSIT_RECONCILIATION_ITEM I WHERE I.RECONCILIATION_RUN_ID=R.RECONCILIATION_RUN_ID),0) OR NVL(R.DIFFERENCE_AMOUNT,0)<>NVL((SELECT SUM(NVL(I.DIFFERENCE_AMOUNT,0)) FROM DPS2.DEPOSIT_RECONCILIATION_ITEM I WHERE I.RECONCILIATION_RUN_ID=R.RECONCILIATION_RUN_ID),0)); chk('reconciliation run totals coherent',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_DISCREPANCY D JOIN DPS2.DEPOSIT_RECONCILIATION_ITEM I ON I.RECONCILIATION_ITEM_ID=D.RECONCILIATION_ITEM_ID WHERE NVL(D.DIFFERENCE_AMOUNT,0)<>NVL(D.EXPECTED_AMOUNT,0)-NVL(D.ACTUAL_AMOUNT,0); chk('discrepancy arithmetic coherent',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_DISCREPANCY D WHERE D.EXCEPTION_CASE_ID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM DPS2.DEPOSIT_EXCEPTION_CASE C WHERE C.EXCEPTION_CASE_ID=D.EXCEPTION_CASE_ID); chk('discrepancy exception trace coherent',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_CORRECTION_ENTRY E WHERE E.ORIGINAL_TRANSACTION_ID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM DPS2.DEPOSIT_TRANSACTION T WHERE T.TRANSACTION_ID=E.ORIGINAL_TRANSACTION_ID); chk('correction original transaction trace coherent',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_CORRECTION_ENTRY E WHERE E.CORRECTIVE_TRANSACTION_ID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM DPS2.DEPOSIT_TRANSACTION T WHERE T.TRANSACTION_ID=E.CORRECTIVE_TRANSACTION_ID); chk('correction corrective transaction trace coherent',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.CORRESPONDENT_RECONCILIATION_PROFILE P WHERE NOT EXISTS(SELECT 1 FROM DPS2.CORRESPONDENT_ACCOUNT_EXTENSION E WHERE E.CORRESPONDENT_ACCOUNT_EXTENSION_ID=P.CORRESPONDENT_ACCOUNT_EXTENSION_ID); chk('correspondent profile trace coherent',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_REWARD_ENROLLMENT E WHERE NOT EXISTS(SELECT 1 FROM DPS2.DEPOSIT_REWARD_PROGRAM P WHERE P.PROGRAM_ID=E.PROGRAM_ID) OR NOT EXISTS(SELECT 1 FROM DPS2.DEPOSIT_ACCOUNT A WHERE A.ACCOUNT_ID=E.ACCOUNT_ID); chk('reward enrollment trace coherent',v=0);
  SELECT COUNT(*) INTO v FROM DPS2.DEPOSIT_LOTTERY_WINNER W WHERE W.PAYMENT_TRANSACTION_ID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM DPS2.DEPOSIT_TRANSACTION T WHERE T.TRANSACTION_ID=W.PAYMENT_TRANSACTION_ID); chk('reward winner payment trace coherent',v=0);
  DBMS_OUTPUT.PUT_LINE('------------------------------------------------------------'); DBMS_OUTPUT.PUT_LINE('PHASE11M_DB_VERIFIER_PASS='||p); DBMS_OUTPUT.PUT_LINE('PHASE11M_DB_VERIFIER_FAIL='||f); IF f>0 THEN RAISE_APPLICATION_ERROR(-21269,'Phase11M DB verifier failed: '||f); END IF; DBMS_OUTPUT.PUT_LINE('PHASE11M_DB_BASELINE_PASS');
END;
/
